package com.jiugeng.erp.product;
import static com.jiugeng.erp.product.ProductTypes.*;import com.jiugeng.erp.catalogmedia.CatalogImageGateway;import com.jiugeng.erp.iam.*;import com.jiugeng.erp.materialinventory.ProductMaterialAssignmentGateway;import com.jiugeng.erp.supplier.SupplierAssignmentGateway;import java.math.BigDecimal;import java.net.URI;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class ProductService{private final ProductRepository repo;private final SupplierAssignmentGateway suppliers;private final ProductMaterialAssignmentGateway materials;private final CatalogImageGateway images;private final AuditTrail audit;private final org.springframework.context.ApplicationEventPublisher events;
ProductService(ProductRepository repo,SupplierAssignmentGateway suppliers,ProductMaterialAssignmentGateway materials,CatalogImageGateway images,AuditTrail audit,org.springframework.context.ApplicationEventPublisher events){this.repo=repo;this.suppliers=suppliers;this.materials=materials;this.images=images;this.audit=audit;this.events=events;}
@Transactional(readOnly=true)List<ProductView> products(boolean supplierAccess){return repo.findAll(supplierAccess);}
@Transactional(readOnly=true)ProductView product(String id,boolean supplierAccess){return repo.findById(id,supplierAccess).orElseThrow(()->missing(id));}
@Transactional(readOnly=true)SkuPage skus(String field,String q,boolean exact,VariantStatus status,ProductStatus productStatus,String productType,Boolean hasImage,Boolean hasSupplier,Boolean hasMaterial,String sort,String direction,int page,int size,boolean supplierAccess){List<String> needles=q==null?List.of():q.lines().map(String::trim).filter(v->!v.isBlank()).map(v->v.toUpperCase(Locale.ROOT)).distinct().toList();if(needles.size()>100)throw invalid("批量搜索最多 100 个编码");List<SkuListItem> values=repo.findAll(supplierAccess).stream().flatMap(p->p.variants().stream().map(v->new SkuListItem(p.id(),p.productCode(),p.productName(),p.status(),p.productType(),v,p.status()==ProductStatus.ACTIVE&&v.status()==VariantStatus.ACTIVE,p.updatedAt()))).filter(v->status==null||v.variant().status()==status).filter(v->productStatus==null||v.productStatus()==productStatus).filter(v->productType==null||productType.isBlank()||productType.equals(v.productType())).filter(v->hasImage==null||hasImage==(v.variant().imageAssetId()!=null||v.variant().imageUrl()!=null)).filter(v->hasSupplier==null||hasSupplier==!v.variant().suppliers().isEmpty()).filter(v->hasMaterial==null||hasMaterial==!v.variant().materials().isEmpty()).filter(v->matches(v,field,needles,exact)).toList();Comparator<SkuListItem> comparator="sku".equalsIgnoreCase(sort)?Comparator.comparing(v->v.variant().skuCode(),String.CASE_INSENSITIVE_ORDER):Comparator.comparing(SkuListItem::updatedAt,Comparator.nullsLast(Comparator.naturalOrder()));if("desc".equalsIgnoreCase(direction))comparator=comparator.reversed();values=values.stream().sorted(comparator.thenComparing(v->v.variant().id())).toList();int from=Math.min(page*size,values.size()),to=Math.min(from+size,values.size());return new SkuPage(values.subList(from,to),values.size(),page,size);}
@Transactional ProductView create(ProductInput input,AuthenticatedActor actor,boolean supplierAccess){ValidatedProduct v=validate(input,null);String id=UUID.randomUUID().toString();try{repo.insertProduct(id,v.code,v.normalizedCode,v.name,v.type,v.description,v.status,actor.userId());saveParentImage(id,input.imageAssetId(),null,actor);saveVariants(id,v.variants,false,actor);ProductView created=product(id,supplierAccess);events.publishEvent(new ProductCreated(id,created.variants().stream().map(sku->new ProductCreated.Sku(sku.id(),sku.skuCode(),sku.variantName())).toList(),actor));record(actor,"PRODUCT_CREATE",id,null,snapshot(created));return created;}catch(ProductCreated.RegistrationException e){throw new ProductException(409,"DEFAULT_CUSTOMER_REQUIRED",e.getMessage());}catch(DataIntegrityViolationException e){throw conflict(e);}catch(ProductMaterialAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(SupplierAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(CatalogImageGateway.AttachmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}}
@Transactional ProductView update(String id,ProductInput input,AuthenticatedActor actor,boolean supplierAccess){ProductView before=product(id,true);if(input.version()==null||input.version()!=before.version())throw version();if(input.productCode()==null||!ProductRepository.normalize(before.productCode()).equals(ProductRepository.normalize(input.productCode())))throw new ProductException(409,"PRODUCT_CODE_IMMUTABLE","产品编码保存后不可修改");ValidatedProduct v=validate(input,id);try{if(repo.updateProduct(id,v.name,v.type,v.description,v.status,input.version(),actor.userId())!=1)throw version();saveParentImage(id,input.imageAssetId(),before.imageAssetId(),actor);saveVariants(id,v.variants,true,actor);ProductView after=product(id,supplierAccess);record(actor,"PRODUCT_UPDATE",id,snapshot(before),snapshot(after));return after;}catch(DataIntegrityViolationException e){throw conflict(e);}catch(ProductMaterialAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(SupplierAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(CatalogImageGateway.AttachmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}}
@Transactional ProductView disable(String id,long version,AuthenticatedActor actor,boolean supplierAccess){ProductView before=product(id,true);if(before.status()==ProductStatus.DISABLED)return product(id,supplierAccess);if(repo.disableProduct(id,version,actor.userId())!=1)throw version();ProductView after=product(id,supplierAccess);record(actor,"PRODUCT_DISABLE",id,snapshot(before),snapshot(after));return after;}
@Transactional List<ProductView> batch(List<BatchVariantPatch> patches,AuthenticatedActor actor,boolean supplierAccess){if(patches==null||patches.isEmpty()||patches.size()>100)throw invalid("批量编辑必须包含 1 至 100 个 SKU");if(patches.stream().anyMatch(p->!p.statusSelected()&&!p.itemDimensionsSelected()&&!p.packageDimensionsSelected()&&!p.packageWeightSelected()))throw invalid("批量编辑至少选择一个修改字段");if(patches.stream().anyMatch(p->p.statusSelected()&&p.status()==null))throw invalid("已选择 SKU 状态时状态不能为空");if(patches.stream().map(p->p.productId()+"\u0000"+p.variantId()).distinct().count()!=patches.size())throw invalid("批量编辑不能重复包含同一 SKU");Map<String,List<BatchVariantPatch>> grouped=patches.stream().collect(java.util.stream.Collectors.groupingBy(BatchVariantPatch::productId,LinkedHashMap::new,java.util.stream.Collectors.toList()));List<ProductView> result=new ArrayList<>();for(var entry:grouped.entrySet()){ProductView current=product(entry.getKey(),true);if(entry.getValue().stream().anyMatch(p->p.productVersion()!=current.version()))throw version();Map<String,BatchVariantPatch> requested=entry.getValue().stream().collect(java.util.stream.Collectors.toMap(BatchVariantPatch::variantId,p->p));List<VariantInput> variants=current.variants().stream().map(v->{BatchVariantPatch p=requested.get(v.id());if(p==null)return input(v);if(p.variantVersion()!=v.version())throw version();return new VariantInput(v.id(),v.skuCode(),v.variantName(),v.itemDimensions(),v.packageDimensions(),p.itemDimensionsSelected()?p.itemLengthCm():v.itemLengthCm(),p.itemDimensionsSelected()?p.itemWidthCm():v.itemWidthCm(),p.itemDimensionsSelected()?p.itemHeightCm():v.itemHeightCm(),p.packageDimensionsSelected()?p.packageLengthCm():v.packageLengthCm(),p.packageDimensionsSelected()?p.packageWidthCm():v.packageWidthCm(),p.packageDimensionsSelected()?p.packageHeightCm():v.packageHeightCm(),p.packageWeightSelected()?p.packageWeightGrams():v.packageWeightGrams(),p.statusSelected()?p.status():v.status(),v.imageAssetId(),v.imageUrl(),v.version(),v.suppliers(),v.materials());}).toList();if(!requested.keySet().stream().allMatch(id->current.variants().stream().anyMatch(v->v.id().equals(id))))throw invalid("批量编辑包含不属于产品的 SKU");ProductInput input=new ProductInput(current.productCode(),current.productName(),current.productType(),current.description(),current.status(),current.version(),variants,current.imageAssetId());result.add(update(current.id(),input,actor,supplierAccess));}return result;}
private ValidatedProduct validate(ProductInput input,String productId){if(input==null)throw invalid("产品请求不能为空");String code=required(input.productCode(),"产品编码",64),normalized=ProductRepository.normalize(code);if(repo.productCodeExists(normalized,productId))throw new ProductException(409,"PRODUCT_CODE_EXISTS","产品编码已存在（忽略大小写）");String name=required(input.productName(),"产品名称",200);List<VariantInput> source=input.variants()==null?List.of():input.variants();if(source.isEmpty()||source.size()>100)throw invalid("产品必须包含 1 至 100 个 SKU");Set<String> codes=new HashSet<>();List<ValidatedVariant> variants=new ArrayList<>();for(VariantInput value:source){ValidatedVariant valid=variant(value,productId);if(!codes.add(valid.normalizedSku))throw new ProductException(409,"SKU_CODE_EXISTS","SKU 编码重复（忽略大小写）");variants.add(valid);}return new ValidatedProduct(code,normalized,name,optional(input.productType(),100),optional(input.description(),1000),input.status()==null?ProductStatus.DRAFT:input.status(),variants);}
private ValidatedVariant variant(VariantInput input,String productId){String id=optional(input.id(),36);if(id!=null&&(productId==null||!repo.variantBelongsToProduct(id,productId)))throw invalid("SKU 不属于当前产品");String sku=required(input.skuCode(),"SKU 编码",64),normalized=ProductRepository.normalize(sku);if(repo.skuCodeExists(normalized,id))throw new ProductException(409,"SKU_CODE_EXISTS","SKU 编码已存在（忽略大小写）");BigDecimal grams=input.packageWeightGrams();if(grams!=null&&(grams.signum()<=0||grams.scale()>3||grams.compareTo(new BigDecimal("999999999.999"))>0))throw invalid("包装重量必须为不超过三位小数的正克数");dimensionGroup(input.itemLengthCm(),input.itemWidthCm(),input.itemHeightCm(),"产品规格");dimensionGroup(input.packageLengthCm(),input.packageWidthCm(),input.packageHeightCm(),"包装规格");String imageId=optional(input.imageAssetId(),36),imageUrl=imageUrl(input.imageUrl());if(imageId!=null&&imageUrl!=null)throw new ProductException(400,"PRODUCT_IMAGE_SOURCE_CONFLICT","SKU 图片地址与上传图片只能选择一种");List<SupplierAssignment> supplierValues=input.suppliers()==null?List.of():List.copyOf(input.suppliers());List<MaterialAssignment> materialValues=input.materials()==null?List.of():List.copyOf(input.materials());return new ValidatedVariant(id,sku,normalized,required(input.variantName(),"SKU 名称",200),optional(input.itemDimensions(),200),optional(input.packageDimensions(),200),input.itemLengthCm(),input.itemWidthCm(),input.itemHeightCm(),input.packageLengthCm(),input.packageWidthCm(),input.packageHeightCm(),grams,input.status()==null?VariantStatus.DRAFT:input.status(),imageId,imageUrl,input.version(),supplierValues,materialValues);}
private void saveParentImage(String productId,String requested,String oldImage,AuthenticatedActor actor){
String image=optional(requested,36);images.attach(image,CatalogImageGateway.Purpose.PRODUCT_MAIN,"PRODUCT",productId,actor);
repo.setProductImage(productId,image);images.releaseReplaced(oldImage,image,"PRODUCT",productId);
}
private void saveVariants(String productId,List<ValidatedVariant> values,boolean updating,AuthenticatedActor actor){List<String> existing=updating?repo.findVariantIds(productId):List.of();Set<String> retained=new HashSet<>();for(ValidatedVariant value:values){String id=value.id==null?UUID.randomUUID().toString():value.id;String oldImage=null;if(value.id==null)repo.insertVariant(id,productId,value.sku,value.normalizedSku,value.name,value.itemDimensions,value.packageDimensions,value.itemLength,value.itemWidth,value.itemHeight,value.packageLength,value.packageWidth,value.packageHeight,value.grams,value.status,value.imageId,value.imageUrl,UUID.randomUUID().toString());else{ProductView current=product(productId,true);VariantView prior=current.variants().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow();oldImage=prior.imageAssetId();if(value.version==null||repo.updateVariant(id,value.sku,value.normalizedSku,value.name,value.itemDimensions,value.packageDimensions,value.itemLength,value.itemWidth,value.itemHeight,value.packageLength,value.packageWidth,value.packageHeight,value.grams,value.status,value.imageId,value.imageUrl,value.version)!=1)throw version();}images.attach(value.imageId,CatalogImageGateway.Purpose.SKU_MAIN,"PRODUCT_VARIANT",id,actor);images.releaseReplaced(oldImage,value.imageId,"PRODUCT_VARIANT",id);suppliers.replaceVariantAssignments(id,value.suppliers.stream().map(s->new SupplierAssignmentGateway.Assignment(s.supplierId(),s.purchaseUrl(),s.remark(),s.primary())).toList(),actor);materials.replaceVariantAssignments(productId,id,value.materials.stream().map(m->new ProductMaterialAssignmentGateway.Assignment(m.materialId(),m.standardQuantity(),m.unit(),m.lossRate(),m.remark(),m.enabled())).toList(),actor);retained.add(id);}if(updating)existing.stream().filter(id->!retained.contains(id)).forEach(repo::disableVariant);}
private String imageUrl(String value){String result=optional(value,500);if(result==null)return null;try{URI uri=URI.create(result);if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException();return uri.toASCIIString();}catch(IllegalArgumentException e){throw new ProductException(400,"PRODUCT_IMAGE_URL_INVALID","SKU 图片地址必须是无用户信息的 HTTPS URL");}}
private String required(String v,String label,int max){String r=optional(v,max);if(r==null)throw invalid(label+"不能为空");return r;}private String optional(String v,int max){if(v==null)return null;String r=v.trim();if(r.isEmpty())return null;if(r.length()>max)throw invalid("字段长度超过 "+max);return r;}
private void dimensionGroup(BigDecimal a,BigDecimal b,BigDecimal c,String label){int count=(a==null?0:1)+(b==null?0:1)+(c==null?0:1);if(count!=0&&count!=3)throw invalid(label+"的长、宽、高必须同时填写");for(BigDecimal value:List.of(a==null?BigDecimal.ONE:a,b==null?BigDecimal.ONE:b,c==null?BigDecimal.ONE:c))if(value.signum()<=0||value.scale()>3||value.compareTo(new BigDecimal("999999.999"))>0)throw invalid(label+"必须为不超过三位小数的正厘米数");}
private boolean matches(SkuListItem value,String field,List<String> needles,boolean exact){if(needles.isEmpty())return true;String candidate=switch(field==null?"":field.toUpperCase(Locale.ROOT)){case "SKU"->value.variant().skuCode();case "SKU_NAME","NAME"->value.variant().variantName();case "PRODUCT_CODE"->value.productCode();case "PRODUCT_NAME"->value.productName();default->java.util.stream.Stream.of(value.variant().skuCode(),value.variant().variantName(),value.productCode(),value.productName(),value.variant().specification(),value.variant().itemDimensions(),value.variant().packageDimensions(),dimensions(value.variant().itemLengthCm(),value.variant().itemWidthCm(),value.variant().itemHeightCm()),dimensions(value.variant().packageLengthCm(),value.variant().packageWidthCm(),value.variant().packageHeightCm())).filter(Objects::nonNull).collect(java.util.stream.Collectors.joining(" "));};if(candidate==null)return false;String normalized=candidate.toUpperCase(Locale.ROOT);return needles.stream().anyMatch(needle->exact?normalized.equals(needle):normalized.contains(needle));}
private String dimensions(BigDecimal a,BigDecimal b,BigDecimal c){return a==null||b==null||c==null?"":a.stripTrailingZeros().toPlainString()+"×"+b.stripTrailingZeros().toPlainString()+"×"+c.stripTrailingZeros().toPlainString();}
private VariantInput input(VariantView v){return new VariantInput(v.id(),v.skuCode(),v.variantName(),v.itemDimensions(),v.packageDimensions(),v.itemLengthCm(),v.itemWidthCm(),v.itemHeightCm(),v.packageLengthCm(),v.packageWidthCm(),v.packageHeightCm(),v.packageWeightGrams(),v.status(),v.imageAssetId(),v.imageUrl(),v.version(),v.suppliers(),v.materials());}
private ProductException invalid(String m){return new ProductException(400,"PRODUCT_FIELD_INVALID",m);}private ProductException missing(String id){return new ProductException(404,"PRODUCT_NOT_FOUND","产品不存在："+id);}private ProductException version(){return new ProductException(409,"PRODUCT_VERSION_CONFLICT","产品或 SKU 已被其他用户更新");}private ProductException conflict(Exception e){return new ProductException(409,"PRODUCT_CONFLICT","产品编码、SKU 或关联关系与现有数据冲突");}
private void record(AuthenticatedActor a,String action,String id,Map<String,?>before,Map<String,?>after){audit.record(new AuditTrail.BusinessOperation(a.userId(),a.loginName(),a.displayName(),action,"PRODUCT",id,true,before,after,"产品、SKU、供应商与辅料聚合保存"));}
private Map<String,Object> snapshot(ProductView p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.id());m.put("productCode",p.productCode());m.put("productName",p.productName());m.put("status",p.status());m.put("version",p.version());m.put("imageAssetId",p.imageAssetId());m.put("skuCodes",p.variants().stream().map(VariantView::skuCode).toList());m.put("supplierIds",p.variants().stream().flatMap(v->v.suppliers().stream()).map(SupplierAssignment::supplierId).distinct().toList());return m;}
private record ValidatedProduct(String code,String normalizedCode,String name,String type,String description,ProductStatus status,List<ValidatedVariant> variants){}
private record ValidatedVariant(String id,String sku,String normalizedSku,String name,String itemDimensions,String packageDimensions,BigDecimal itemLength,BigDecimal itemWidth,BigDecimal itemHeight,BigDecimal packageLength,BigDecimal packageWidth,BigDecimal packageHeight,BigDecimal grams,VariantStatus status,String imageId,String imageUrl,Long version,List<SupplierAssignment> suppliers,List<MaterialAssignment> materials){}
}
